CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.adjust_inventory(p_organization_id uuid, p_product_id uuid, p_quantity_delta numeric, p_reason text, p_batch_number text DEFAULT NULL::text, p_expiry_date date DEFAULT NULL::date, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_movement_type text;
  v_current_stock numeric;
  v_new_stock numeric;
  v_transaction_id uuid;
begin
  if p_quantity_delta is null or p_quantity_delta = 0 then
    raise exception 'Quantity change must be a non-zero number';
  end if;
  if p_reason is null or char_length(trim(p_reason)) = 0 then
    raise exception 'A reason is required for stock adjustments';
  end if;
  if char_length(trim(p_reason)) > 500 then
    raise exception 'Reason must be 500 characters or fewer';
  end if;
  if not public.has_inventory_permission(auth.uid()) then
    raise exception 'Permission denied: the Manage Inventory permission is required';
  end if;

  select current_stock into v_current_stock
  from public.products
  where id = p_product_id and organization_id = p_organization_id;

  if v_current_stock is null then
    raise exception 'Product not found in this organization';
  end if;

  v_new_stock := coalesce(v_current_stock, 0) + p_quantity_delta;
  if v_new_stock < 0 then
    raise exception 'Adjustment would make stock negative (current: %, change: %, result: %)',
      v_current_stock, p_quantity_delta, v_new_stock;
  end if;

  v_movement_type := case when p_quantity_delta > 0 then 'adjustment_in' else 'adjustment_out' end;

  insert into public.inventory_transactions
    (organization_id, product_id, movement_type, quantity_delta, reason, batch_number,
     expiry_date, reference_type, reference_id, created_by)
  values
    (p_organization_id, p_product_id, v_movement_type, p_quantity_delta, trim(p_reason),
     nullif(trim(coalesce(p_batch_number, '')), ''), p_expiry_date,
     'adjustment', null, p_created_by)
  returning id into v_transaction_id;

  update public.products
    set current_stock = current_stock + p_quantity_delta, updated_at = now()
    where id = p_product_id and current_stock + p_quantity_delta >= 0;

  if not found then
    raise exception 'Adjustment would make stock negative (current: %, change: %, result: %)',
      v_current_stock, p_quantity_delta, v_new_stock;
  end if;

  return v_transaction_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_purchase_atomic(p_organization_id uuid, p_actor_profile_id uuid, p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tx public.purchase_transactions%rowtype;
  v_item public.purchase_items%rowtype;
  v_supplier public.suppliers%rowtype;
  v_po public.purchase_orders%rowtype;
  v_po_item public.purchase_order_items%rowtype;
  v_line jsonb;
  v_items jsonb := '[]'::jsonb;
  v_total numeric := 0;
  v_sequence bigint;
  v_invoice text;
  v_request text := nullif(p_input->>'request_key', '');
  v_payment text := coalesce(nullif(lower(p_input->>'payment_type'), ''), 'cash');
  v_date date := coalesce(nullif(p_input->>'purchase_date','')::date, current_date);
  v_credit_days integer := coalesce(nullif(p_input->>'credit_days','')::integer, 0);
  v_discount numeric := coalesce(nullif(p_input->>'discount_amount','')::numeric, 0);
  v_tax numeric := coalesce(nullif(p_input->>'tax_amount','')::numeric, 0);
  v_po_id uuid := nullif(p_input->>'purchase_order_id','')::uuid;
begin
  if not exists (select 1 from profiles where id = p_actor_profile_id
    and organization_id = p_organization_id and is_active is distinct from false) then
    raise exception 'Active organization actor required' using errcode = '42501';
  end if;
  if v_request is not null then
    if length(v_request) > 150 then raise exception 'Request key is too long'; end if;
    perform pg_advisory_xact_lock(hashtextextended(p_organization_id::text || ':' || v_request, 0));
    select * into v_tx from purchase_transactions where organization_id = p_organization_id and request_key = v_request;
    if found then
      if v_tx.created_by_profile_id <> p_actor_profile_id then raise exception 'Request key belongs to another actor'; end if;
      if v_tx.request_fingerprint is distinct from md5((p_input - 'request_key')::text) then raise exception 'Request key was already used for a different purchase'; end if;
      return jsonb_build_object('transaction', to_jsonb(v_tx), 'items',
        (select coalesce(jsonb_agg(to_jsonb(i)), '[]'::jsonb) from purchase_items i where purchase_transaction_id = v_tx.id), 'replayed', true);
    end if;
  end if;
  if jsonb_typeof(p_input->'lines') is distinct from 'array' then raise exception 'Purchase lines must be an array'; end if;
  if jsonb_array_length(p_input->'lines') = 0 then raise exception 'At least one purchase line is required'; end if;
  if v_payment not in ('cash','credit') or v_credit_days < 0 or v_credit_days > 36500 then raise exception 'Invalid purchase payment terms'; end if;
  if v_discount < 0 or v_tax < 0 or v_discount::text in ('NaN','Infinity','-Infinity') or v_tax::text in ('NaN','Infinity','-Infinity') then raise exception 'Invalid purchase adjustments'; end if;

  select * into v_supplier from suppliers where id = (p_input->>'supplier_id')::uuid
    and organization_id = p_organization_id for update;
  if not found then raise exception 'Supplier not found'; end if;
  if v_po_id is not null then
    select * into v_po from purchase_orders where id = v_po_id and organization_id = p_organization_id for update;
    if not found or v_po.supplier_id <> v_supplier.id or v_po.status not in ('ordered','partial') then raise exception 'Purchase order cannot be received'; end if;
  end if;
  -- Consistent product lock order prevents opposing multi-product purchases deadlocking.
  perform 1 from products where organization_id = p_organization_id and id::text in
    (select value->>'product_id' from jsonb_array_elements(p_input->'lines')) order by id for update;
  for v_line in select value from jsonb_array_elements(p_input->'lines') loop
    v_item := jsonb_populate_record(null::public.purchase_items, v_line);
    if v_item.quantity is null or v_item.quantity <= 0 or v_item.quantity::text in ('NaN','Infinity','-Infinity')
      or v_item.purchase_price is null or v_item.purchase_price < 0 or v_item.purchase_price::text in ('NaN','Infinity','-Infinity')
      or (v_item.selling_price is not null and (v_item.selling_price < 0 or v_item.selling_price::text in ('NaN','Infinity','-Infinity')))
      or coalesce(v_item.unit_mode,'main') not in ('main','subunit') then raise exception 'Invalid purchase line'; end if;
    if not exists (select 1 from products where id = v_item.product_id and organization_id = p_organization_id) then raise exception 'Product not found in organization'; end if;
    if v_po_id is not null then
      select * into v_po_item from purchase_order_items where id = (v_line->>'order_item_id')::uuid
        and purchase_order_id = v_po_id and product_id = v_item.product_id for update;
      if not found or v_po_item.quantity_received + v_item.quantity > v_po_item.quantity_ordered then raise exception 'Receipt exceeds purchase order remaining quantity'; end if;
      update purchase_order_items set quantity_received = quantity_received + v_item.quantity,
        unit_price = v_item.purchase_price, batch_number = v_item.batch_number, expiry_date = v_item.expiry_date where id = v_po_item.id;
    end if;
    v_total := v_total + v_item.quantity * v_item.purchase_price;
  end loop;
  v_total := v_total - v_discount + v_tax;
  if v_total < 0 then raise exception 'Discount exceeds purchase total'; end if;
  v_invoice := nullif(p_input->>'import_invoice_number','');
  if v_invoice is null then
    v_sequence := public.next_invoice_number(p_organization_id, 'purchase');
    if v_sequence is null or v_sequence <= 0 then raise exception 'Invalid invoice sequence'; end if;
    v_invoice := 'P-' || (50000 + v_sequence)::text;
  end if;
  insert into purchase_transactions (organization_id, supplier_id, invoice_number, supplier_invoice_number,
    purchase_date, payment_type, credit_due_date, notes, total_amount, discount_amount, tax_amount,
    status, invoice_type, created_by_profile_id, request_key, request_fingerprint)
  values (p_organization_id, v_supplier.id, v_invoice, nullif(p_input->>'supplier_invoice_number',''), v_date, v_payment,
    case when v_payment = 'credit' then coalesce(nullif(p_input->>'credit_due_date','')::date, v_date + v_credit_days) else null end,
    nullif(p_input->>'notes',''), v_total, v_discount, v_tax, 'confirmed', 'purchase', p_actor_profile_id, v_request, md5((p_input - 'request_key')::text))
  returning * into v_tx;
  for v_line in select value from jsonb_array_elements(p_input->'lines') loop
    v_item := jsonb_populate_record(null::public.purchase_items, v_line);
    insert into purchase_items (purchase_transaction_id, organization_id, product_id, quantity, purchase_price,
      selling_price, batch_number, expiry_date, unit_mode)
    values (v_tx.id, p_organization_id, v_item.product_id, v_item.quantity, v_item.purchase_price,
      v_item.selling_price, v_item.batch_number, v_item.expiry_date, coalesce(v_item.unit_mode,'main')) returning * into v_item;
    v_items := v_items || jsonb_build_array(to_jsonb(v_item));
    if v_item.selling_price is not null then
      update products set default_selling_price = v_item.selling_price where id = v_item.product_id and organization_id = p_organization_id;
    end if;
  end loop;
  update suppliers set outstanding_balance = coalesce(outstanding_balance,0) + case when v_payment = 'credit' then v_total else 0 end,
    last_purchase_date = greatest(last_purchase_date, v_date), updated_at = now() where id = v_supplier.id and organization_id = p_organization_id;
  if v_po_id is not null then
    update purchase_orders set status = case when exists (select 1 from purchase_order_items where purchase_order_id = v_po_id
      and quantity_received < quantity_ordered) then 'partial' else 'received' end, updated_at = now() where id = v_po_id;
  end if;
  insert into audit_logs (organization_id, actor_profile_id, action, entity_type, entity_id, entity_label, description, new_values)
    values (p_organization_id, p_actor_profile_id, 'purchase_created', 'purchase_transaction', v_tx.id, v_invoice,
      'Created purchase ' || v_invoice, jsonb_build_object('total_amount',v_total,'supplier_id',v_supplier.id,'purchase_order_id',v_po_id));
  return jsonb_build_object('transaction',to_jsonb(v_tx),'items',v_items,'purchase_order_status',
    (select status from purchase_orders where id = v_po_id));
end $function$

CREATE OR REPLACE FUNCTION public.delete_purchase_atomic(p_organization_id uuid, p_actor_profile_id uuid, p_purchase_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tx public.purchase_transactions%rowtype;
begin
  if not exists (select 1 from profiles where id = p_actor_profile_id and organization_id = p_organization_id and is_active is distinct from false) then
    raise exception 'Active organization actor required' using errcode = '42501'; end if;
  select * into v_tx from purchase_transactions where id = p_purchase_id and organization_id = p_organization_id for update;
  if not found then raise exception 'Purchase not found'; end if;
  -- Never silently remove financial links or receipts. These must be reversed explicitly.
  if exists (select 1 from supplier_payment_allocations where purchase_transaction_id = p_purchase_id)
    or exists (select 1 from expenses where purchase_transaction_id = p_purchase_id)
    or exists (select 1 from purchase_returns where purchase_transaction_id = p_purchase_id)
    or exists (select 1 from audit_logs where organization_id = p_organization_id and entity_id::text = p_purchase_id::text
      and new_values->>'purchase_order_id' is not null) then raise exception 'Purchase has linked records; reverse them before deleting'; end if;
  perform 1 from suppliers where id = v_tx.supplier_id and organization_id = p_organization_id for update;
  perform 1 from products where organization_id = p_organization_id and id in
    (select product_id from purchase_items where purchase_transaction_id = p_purchase_id) order by id for update;
  delete from purchase_items where purchase_transaction_id = p_purchase_id and organization_id = p_organization_id;
  delete from purchase_transactions where id = p_purchase_id and organization_id = p_organization_id;
  if lower(v_tx.payment_type) = 'credit' then
    update suppliers set outstanding_balance = coalesce(outstanding_balance,0) - coalesce(v_tx.total_amount,0), updated_at = now()
      where id = v_tx.supplier_id and organization_id = p_organization_id;
  end if;
  insert into audit_logs (organization_id, actor_profile_id, action, entity_type, entity_id, entity_label, description, old_values)
    values (p_organization_id,p_actor_profile_id,'purchase_deleted','purchase_transaction',p_purchase_id,v_tx.invoice_number,
      'Deleted purchase ' || v_tx.invoice_number,to_jsonb(v_tx));
end $function$

CREATE OR REPLACE FUNCTION public.import_historical_records(p_org uuid, p_actor uuid, p_cutover date, p_file text, p_kind text, p_records jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  doc jsonb; line jsonb; party uuid; related uuid; amount numeric; subtotal numeric;
  qty numeric; price numeric; discount numeric; bonus numeric; header_discount numeric; tax numeric;
  number text; source text; record_day date; count_saved integer := 0; is_payment boolean; is_supplier boolean;
begin
  if p_kind not in ('sale','purchase','customer_payment','supplier_payment') or p_kind is null then raise exception 'Unsupported history type'; end if;
  if p_cutover is null or nullif(btrim(p_file),'') is null then raise exception 'Start date and source file are required'; end if;
  if jsonb_typeof(p_records) is distinct from 'array' or jsonb_array_length(p_records) not between 1 and 5000 then raise exception 'Provide 1 to 5000 historical documents'; end if;
  if not exists(select 1 from profiles where id=p_actor and organization_id=p_org) then raise exception 'Importer does not belong to this organization'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_org::text, 731));
  if exists(select 1 from historical_records where organization_id=p_org and cutover_date<>p_cutover) then raise exception 'Use the same start date as previously imported history for this business'; end if;
  is_payment := p_kind in ('customer_payment','supplier_payment');
  is_supplier := p_kind in ('purchase','supplier_payment');
  for doc in select value from jsonb_array_elements(p_records) loop
    number := nullif(btrim(doc->>'record_number'),''); source := nullif(btrim(doc->>'source_system'),'');
    party := (doc->>'party_id')::uuid; record_day := (doc->>'record_date')::date;
    amount := (doc->>'total_amount')::numeric; related := nullif(doc->>'related_id','')::uuid;
    if number is null or source is null or record_day is null or record_day >= p_cutover then raise exception 'Each historical record needs a source, reference and date before the start date'; end if;
    if amount is null or amount < 0 or amount >= 1e15 then raise exception 'Invalid historical amount'; end if;
    if is_supplier then
      if not exists(select 1 from suppliers where id=party and organization_id=p_org) then raise exception 'Supplier not found in this organization'; end if;
    else
      if not exists(select 1 from customers where id=party and organization_id=p_org) then raise exception 'Customer not found in this organization'; end if;
    end if;
    if (p_kind='sale' and exists(select 1 from sales_transactions where organization_id=p_org and invoice_type='sales' and lower(btrim(invoice_number))=lower(number)))
      or (p_kind='purchase' and exists(select 1 from purchase_transactions where organization_id=p_org and invoice_type='purchase' and lower(btrim(invoice_number))=lower(number)))
      or (p_kind='customer_payment' and exists(select 1 from customer_payments where organization_id=p_org and customer_id=party and lower(btrim(reference_number))=lower(number)))
      or (p_kind='supplier_payment' and exists(select 1 from supplier_payments where organization_id=p_org and supplier_id=party and lower(btrim(reference_number))=lower(number))) then
      raise exception 'Reference % already exists in live transactions', number;
    end if;
    if is_payment then
      if amount <= 0 or amount <> round(amount,2) then raise exception 'Payment must be positive with at most two decimal places'; end if;
      if related is not null and not exists(select 1 from historical_records where id=related and organization_id=p_org and party_id=party and kind=case when is_supplier then 'purchase' else 'sale' end and lower(btrim(source_system))=lower(source)) then raise exception 'Related invoice does not match this party and source'; end if;
    else
      if related is not null then raise exception 'Invoices cannot be linked as payments'; end if;
      if doc->>'payment_type' is null or doc->>'payment_type' not in ('cash','credit') then raise exception 'Invalid invoice payment type'; end if;
      if jsonb_typeof(doc->'lines') is distinct from 'array' or jsonb_array_length(doc->'lines') not between 1 and 5000 then raise exception 'Invoice lines are required'; end if;
      subtotal := 0;
      for line in select value from jsonb_array_elements(doc->'lines') loop
        if not exists(select 1 from products where id=(line->>'product_id')::uuid and organization_id=p_org) then raise exception 'Product not found in this organization'; end if;
        qty := (line->>'quantity')::numeric; price := (line->>'unit_price')::numeric;
        discount := coalesce((line->>'discount')::numeric,0); bonus := coalesce((line->>'bonus')::numeric,0);
        if qty is null or qty<=0 or qty>=1e15 or price is null or price<0 or price>=1e15 or discount<0 or discount>qty*price or bonus<0 or bonus>=1e15 then raise exception 'Invalid historical line amount or quantity'; end if;
        if line->>'unit_mode' is null or line->>'unit_mode' not in ('main','subunit') then raise exception 'Invalid historical unit mode'; end if;
        subtotal := subtotal + qty*price-discount;
      end loop;
      header_discount:=coalesce((doc->>'discount_amount')::numeric,0); tax:=coalesce((doc->>'tax_amount')::numeric,0);
      if header_discount<0 or header_discount>subtotal or tax<0 or tax>=1e15 or abs(round(subtotal-header_discount+tax,2)-amount)>0.01 then raise exception 'Historical invoice total does not reconcile'; end if;
      if doc->>'paid_amount' is not null and ((doc->>'paid_amount')::numeric<0 or (doc->>'paid_amount')::numeric>amount) then raise exception 'Invalid source paid amount'; end if;
    end if;
    insert into historical_records(organization_id,kind,source_system,record_number,party_id,party_name,record_date,cutover_date,total_amount,related_id,source_file,payload,imported_by)
      values(p_org,p_kind,source,number,party,coalesce(doc->>'party_name',''),record_day,p_cutover,amount,related,p_file,doc,p_actor);
    count_saved := count_saved+1;
  end loop;
  return count_saved;
end $function$

CREATE OR REPLACE FUNCTION public.inventory_sync_purchase_item()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_org uuid;
  v_product_id uuid;
  v_delta numeric;
  v_upp numeric;
  v_batch text;
  v_expiry date;
  v_ref uuid;
  v_created_at timestamptz;
begin
  if tg_op = 'DELETE' then
    v_org := coalesce(old.organization_id,
      (select organization_id from public.purchase_transactions where id = old.purchase_transaction_id));
    v_product_id := old.product_id;
    v_delta := -coalesce(old.quantity, 0);
    v_batch := old.batch_number;
    v_expiry := old.expiry_date;
    v_ref := old.purchase_transaction_id;
    v_created_at := coalesce(old.created_at, now());
  else
    v_org := coalesce(new.organization_id,
      (select organization_id from public.purchase_transactions where id = new.purchase_transaction_id));
    v_product_id := new.product_id;
    v_delta := coalesce(new.quantity, 0);
    if tg_op = 'UPDATE' then
      v_delta := v_delta - coalesce(old.quantity, 0);
    end if;
    v_batch := new.batch_number;
    v_expiry := new.expiry_date;
    v_ref := new.purchase_transaction_id;
    v_created_at := coalesce(new.created_at, now());
  end if;

  if v_product_id is null or v_org is null or v_delta = 0 then
    return coalesce(new, old);
  end if;

  if coalesce((case when tg_op = 'DELETE' then old.unit_mode else new.unit_mode end), 'main') = 'subunit' then
    select units_per_pack into v_upp from public.products where id = v_product_id;
    if v_upp is not null and v_upp > 0 then
      v_delta := v_delta / v_upp;
    end if;
  end if;

  insert into public.inventory_transactions
    (organization_id, product_id, movement_type, quantity_delta, batch_number, expiry_date,
     reference_type, reference_id, created_at)
  values
    (v_org, v_product_id, 'purchase_in', v_delta, v_batch, v_expiry,
     'purchase_transaction', v_ref, v_created_at);

  update public.products
    set current_stock = current_stock + v_delta, updated_at = now()
    where id = v_product_id;

  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.inventory_sync_purchase_return_item()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_organization_id uuid;
  v_product_id uuid;
  v_parent_id uuid;
  v_stock_delta numeric;
  v_old_stock_quantity numeric := 0;
  v_new_stock_quantity numeric := 0;
  v_units_per_pack numeric;
  v_current_stock numeric;
  v_batch_number text;
  v_expiry_date date;
  v_created_at timestamptz;
begin
  if tg_op = 'DELETE' then
    v_organization_id := old.organization_id;
    v_product_id := old.product_id;
    v_parent_id := old.purchase_return_id;
    v_batch_number := old.batch_number;
    v_expiry_date := old.expiry_date;
    v_created_at := old.created_at;
  else
    v_organization_id := new.organization_id;
    v_product_id := new.product_id;
    v_parent_id := new.purchase_return_id;
    v_batch_number := new.batch_number;
    v_expiry_date := new.expiry_date;
    v_created_at := new.created_at;
  end if;

  if v_organization_id is null or v_product_id is null then
    raise exception using
      errcode = '23514',
      message = 'Purchase return line is missing its organization or product';
  end if;

  if tg_op = 'UPDATE'
     and (new.purchase_return_id is distinct from old.purchase_return_id
       or new.product_id is distinct from old.product_id
       or new.organization_id is distinct from old.organization_id) then
    raise exception using
      errcode = '23514',
      message = 'Purchase return line ownership cannot be reassigned';
  end if;

  select p.units_per_pack, p.current_stock
    into v_units_per_pack, v_current_stock
    from public.products p
   where p.id = v_product_id
     and p.organization_id = v_organization_id
   for update;

  if not found then
    raise exception using
      errcode = '23514',
      message = 'Purchase return line product is not in its organization';
  end if;

  if tg_op <> 'DELETE' then
    v_new_stock_quantity := coalesce(new.quantity, 0);
    if coalesce(new.unit_mode, 'main') = 'subunit'
       and v_units_per_pack is not null
       and v_units_per_pack > 0 then
      v_new_stock_quantity := v_new_stock_quantity / v_units_per_pack;
    end if;
  end if;

  if tg_op = 'UPDATE' or tg_op = 'DELETE' then
    v_old_stock_quantity := coalesce(old.quantity, 0);
    if coalesce(old.unit_mode, 'main') = 'subunit'
       and v_units_per_pack is not null
       and v_units_per_pack > 0 then
      v_old_stock_quantity := v_old_stock_quantity / v_units_per_pack;
    end if;
  end if;

  if tg_op = 'DELETE' then
    v_stock_delta := v_old_stock_quantity;
  else
    v_stock_delta := v_old_stock_quantity - v_new_stock_quantity;
  end if;

  if v_stock_delta = 0 then
    return coalesce(new, old);
  end if;

  if v_stock_delta < 0 and v_current_stock + v_stock_delta < 0 then
    raise exception using
      errcode = '23514',
      message = 'Purchase return cannot reduce stock below zero';
  end if;

  update public.products p
     set current_stock = p.current_stock + v_stock_delta,
         updated_at = pg_catalog.now()
   where p.id = v_product_id
     and p.organization_id = v_organization_id
     and (v_stock_delta >= 0 or p.current_stock + v_stock_delta >= 0);

  if not found then
    raise exception using
      errcode = '23514',
      message = 'Purchase return stock update was rejected';
  end if;

  insert into public.inventory_transactions
    (organization_id, product_id, movement_type, quantity_delta, reason,
     batch_number, expiry_date, reference_type, reference_id, created_at)
  values
    (v_organization_id, v_product_id, 'return_out', v_stock_delta, null,
     v_batch_number, v_expiry_date, 'purchase_return', v_parent_id,
     coalesce(v_created_at, pg_catalog.now()));

  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.inventory_sync_sale_item()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  old_org uuid; new_org uuid; old_product uuid; new_product uuid;
  old_ref uuid; new_ref uuid; old_main numeric := 0; new_main numeric := 0;
  pack numeric; movement record;
begin
  if tg_op <> 'INSERT' then
    old_org := coalesce(old.organization_id, (select organization_id from public.sales_transactions where id = old.sales_transaction_id));
    old_product := old.product_id; old_ref := old.sales_transaction_id;
    old_main := coalesce(old.quantity, 0);
    if coalesce(old.unit_mode, 'main') = 'subunit' then
      select units_per_pack into pack from public.products where id = old_product;
      if pack > 0 then old_main := old_main / pack; end if;
    end if;
    old_main := old_main + coalesce(old.inventory_bonus_main, 0);
  end if;
  if tg_op <> 'DELETE' then
    new_org := coalesce(new.organization_id, (select organization_id from public.sales_transactions where id = new.sales_transaction_id));
    new_product := new.product_id; new_ref := new.sales_transaction_id;
    new_main := coalesce(new.quantity, 0);
    if coalesce(new.unit_mode, 'main') = 'subunit' then
      select units_per_pack into pack from public.products where id = new_product;
      if pack is null or pack <= 0 then raise exception 'Configure units per pack before selling sub-units'; end if;
      new_main := new_main / pack;
    end if;
    new_main := new_main + coalesce(new.inventory_bonus_main, 0);
  end if;
  -- Combine old and new quantities before checking stock. Unit changes and
  -- bonus/paid-quantity changes therefore apply their net effect exactly once.
  for movement in
    select org, product, reference, sum(delta) as delta
    from (values (old_org, old_product, old_ref, old_main), (new_org, new_product, new_ref, -new_main)) as changes(org, product, reference, delta)
    where org is not null and product is not null
    group by org, product, reference having sum(delta) <> 0
  loop
    if movement.delta < 0 and public.resolve_overselling_policy(movement.org, movement.product) = 'block' then
      update public.products set current_stock = coalesce(current_stock, 0) + movement.delta, updated_at = now()
      where id = movement.product and organization_id = movement.org and coalesce(current_stock, 0) + movement.delta >= 0;
      if not found then raise exception 'Insufficient stock, including bonus units, for product %', movement.product; end if;
    else
      update public.products set current_stock = coalesce(current_stock, 0) + movement.delta, updated_at = now()
      where id = movement.product and organization_id = movement.org;
      if not found then raise exception 'Product does not belong to this organization'; end if;
    end if;
    insert into public.inventory_transactions(organization_id, product_id, movement_type, quantity_delta, reason, batch_number, reference_type, reference_id, created_at)
    values (movement.org, movement.product, 'sale_out', movement.delta, null, null, 'sales_transaction', movement.reference, now());
  end loop;
  return coalesce(new, old);
end $function$

CREATE OR REPLACE FUNCTION public.next_invoice_number(p_organization_id uuid, p_invoice_type text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_next integer;
  v_actor uuid := auth.uid();
  v_jwt_role text := auth.jwt() ->> 'role';
begin
  if p_organization_id is null then
    raise exception 'Invoice organization is required' using errcode = '22023';
  end if;
  if p_invoice_type is null or p_invoice_type not in (
    'sales', 'purchase', 'sales_return', 'purchase_return', 'purchase_order', 'sales_order'
  ) then
    raise exception 'Unknown invoice type' using errcode = '22023';
  end if;

  if v_jwt_role is distinct from 'service_role' and (
    v_actor is null or not exists (
      select 1
      from public.profiles p
      where p.id = v_actor
        and p.organization_id = p_organization_id
        and p.is_active is true
    )
  ) then
    raise exception 'Active organization membership is required' using errcode = '42501';
  end if;

  insert into public.invoice_sequences (organization_id, invoice_type, current_number, updated_at)
  values (p_organization_id, p_invoice_type, 1, pg_catalog.now())
  on conflict (organization_id, invoice_type)
  do update set current_number = public.invoice_sequences.current_number + 1,
                updated_at = pg_catalog.now()
  returning current_number into v_next;

  return v_next;
end;
$function$

CREATE OR REPLACE FUNCTION public.prepare_sale_inventory_bonus()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pack numeric;
begin
  if coalesce(new.bonus, 0) < 0 then raise exception 'Bonus cannot be negative'; end if;
  new.inventory_bonus_main := coalesce(new.bonus, 0);
  if coalesce(new.unit_mode, 'main') = 'subunit' then
    select units_per_pack into pack from public.products where id = new.product_id;
    if pack is null or pack <= 0 then raise exception 'Configure units per pack before selling sub-units'; end if;
    new.inventory_bonus_main := new.inventory_bonus_main / pack;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.process_collection_decision(p_organization_id uuid, p_collection_id uuid, p_actor_profile_id uuid, p_action text, p_notes text DEFAULT NULL::text, p_processed_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_collection public.collections%rowtype;
  v_customer public.customers%rowtype;
  v_invoice record;
  v_payment_id uuid;
  v_employee_profile_id uuid;
  v_payment_method text;
  v_remaining numeric := 0;
  v_allocation numeric := 0;
  v_allocated numeric := 0;
begin
  if p_organization_id is null or p_collection_id is null or p_actor_profile_id is null then
    raise exception using
      errcode = '22023',
      message = 'process_collection_decision: organization, collection, and actor are required';
  end if;

  if p_action not in ('approve', 'reject') then
    raise exception using
      errcode = '22023',
      message = 'process_collection_decision: action must be approve or reject';
  end if;

  if p_processed_at is null then
    raise exception using
      errcode = '22023',
      message = 'process_collection_decision: processed time is required';
  end if;

  perform 1
  from public.profiles
  where id = p_actor_profile_id
    and organization_id = p_organization_id
    and is_active is distinct from false;

  if not found then
    raise exception using
      errcode = '42501',
      message = 'process_collection_decision: actor does not belong to this organization';
  end if;

  select *
  into v_collection
  from public.collections
  where id = p_collection_id
    and organization_id = p_organization_id
  for update;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'process_collection_decision: collection not found';
  end if;

  if v_collection.status <> 'pending' then
    raise exception using
      errcode = 'P0001',
      message = format('process_collection_decision: collection is already %s', v_collection.status);
  end if;

  if v_collection.amount is null or v_collection.amount <= 0 then
    raise exception using
      errcode = '22023',
      message = 'process_collection_decision: collection amount must be greater than zero';
  end if;

  update public.collections
  set status = case when p_action = 'approve' then 'approved' else 'rejected' end,
      approved_by = p_actor_profile_id,
      approved_at = p_processed_at,
      notes = coalesce(p_notes, v_collection.notes),
      updated_at = p_processed_at
  where id = p_collection_id
    and organization_id = p_organization_id
  returning * into v_collection;

  if p_action = 'approve' then
    -- The customer lock serializes concurrent approvals for the same customer,
    -- preventing lost balance updates and duplicate over-allocation.
    select *
    into v_customer
    from public.customers
    where id = v_collection.customer_id
      and organization_id = p_organization_id
    for update;

    if not found then
      raise exception using
        errcode = 'P0002',
        message = 'process_collection_decision: customer not found';
    end if;

    v_payment_method := case
      when v_collection.method = 'bank_transfer' then 'bank'
      when v_collection.method = 'cash' then 'cash'
      else 'other'
    end;

    insert into public.customer_payments (
      organization_id,
      customer_id,
      amount,
      payment_date,
      payment_method,
      notes
    ) values (
      p_organization_id,
      v_collection.customer_id,
      v_collection.amount,
      (p_processed_at at time zone 'UTC')::date,
      v_payment_method,
      format(
        'Approved collection %s%s',
        p_collection_id,
        case
          when v_collection.reference_number is not null
            then format(' (%s)', v_collection.reference_number)
          else ''
        end
      )
    )
    returning id into v_payment_id;

    v_remaining := v_collection.amount;

    for v_invoice in
      select
        transaction.id,
        greatest(
          coalesce(transaction.total_amount, 0) - coalesce(sum(allocation.amount), 0),
          0
        ) as amount_due
      from public.sales_transactions as transaction
      left join public.customer_payment_allocations as allocation
        on allocation.sales_transaction_id = transaction.id
       and allocation.organization_id = p_organization_id
      where transaction.organization_id = p_organization_id
        and transaction.customer_id = v_collection.customer_id
        and transaction.payment_type = 'credit'
        and transaction.status not in ('cancelled', 'void')
      group by transaction.id, transaction.total_amount, transaction.sale_date, transaction.created_at
      order by transaction.sale_date asc nulls last, transaction.created_at asc, transaction.id asc
    loop
      exit when v_remaining <= 0;
      v_allocation := least(v_invoice.amount_due, v_remaining);

      if v_allocation > 0 then
        insert into public.customer_payment_allocations (
          organization_id,
          customer_payment_id,
          sales_transaction_id,
          amount
        ) values (
          p_organization_id,
          v_payment_id,
          v_invoice.id,
          v_allocation
        );
        v_remaining := v_remaining - v_allocation;
        v_allocated := v_allocated + v_allocation;
      end if;
    end loop;

    update public.customers
    set outstanding_balance = greatest(
          0,
          coalesce(v_customer.outstanding_balance, 0) - v_collection.amount
        ),
        updated_at = p_processed_at
    where id = v_collection.customer_id
      and organization_id = p_organization_id;
  end if;

  select profile_id
  into v_employee_profile_id
  from public.employees
  where id = v_collection.employee_id
    and organization_id = p_organization_id;

  return jsonb_build_object(
    'collection', to_jsonb(v_collection),
    'employee_profile_id', v_employee_profile_id,
    'payment_id', v_payment_id,
    'allocated_amount', v_allocated,
    'unapplied_amount', greatest(v_remaining, 0)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_overselling_policy(p_organization_id uuid, p_product_id integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_product_policy text;
  v_category_id uuid;
  v_policy text;
  v_org_policy text;
  v_hops integer := 0;
begin
  select overselling_policy, category_id
    into v_product_policy, v_category_id
  from public.products
  where id = p_product_id and organization_id = p_organization_id;

  if not found then
    raise exception 'resolve_overselling_policy: product % not found in organization %',
      p_product_id, p_organization_id;
  end if;

  if v_product_policy is not null then
    return v_product_policy;
  end if;

  while v_category_id is not null and v_hops < 20 loop
    select overselling_policy, parent_category_id
      into v_policy, v_category_id
    from public.categories
    where id = v_category_id and organization_id = p_organization_id;

    if not found then
      exit;
    end if;

    if v_policy is not null then
      return v_policy;
    end if;

    v_hops := v_hops + 1;
  end loop;

  select overselling_policy into v_org_policy
  from public.organizations
  where id = p_organization_id;

  return coalesce(v_org_policy, 'allow');
end;
$function$

